code = "package org.casbin.jcasbin.rbac;\n\nimport org.junit.Before;\nimport org.junit.Test;\n\nimport java.lang.reflect.Field;\nimport java.util.Map;\nimport java.util.function.BiPredicate;\n\nimport static org.junit.Assert.*;\n\npublic class AddLinkTests {\n\n    private DomainManager domainManager;\n\n    @Before\n    public void setUp() {\n        domainManager = new DomainManager(10);\n    }\n\n    @Test\n    public void testAddLinkWithoutDomain() {\n        domainManager.addLink(\"alice\", \"admin\");\n        assertTrue(domainManager.hasLink(\"alice\", \"admin\", \"\"));\n    }\n\n    @Test\n    public void testAddLinkWithSingleDomain() {\n        domainManager.addLink(\"alice\", \"admin\", \"domain1\");\n        assertTrue(domainManager.hasLink(\"alice\", \"admin\", \"domain1\"));\n    }\n\n    @Test\n    public void testAddLinkWithMultipleDomains() {\n        domainManager.addLink(\"bob\", \"member\", \"domain1\", \"domain2\");\n        assertTrue(domainManager.hasLink(\"bob\", \"member\", \"domain1\", \"domain2\"));\n    }\n\n    @Test\n    public void testAddLinkPropagatesWithDomainMatch() throws Exception {\n        BiPredicate<String, String> matchingFunc = null;\n        // domainMatchingFunc: matches everything for test purposes\n        BiPredicate<String, String> domainMatchingFunc = (s1, s2) -> true;\n\n        DomainManager manager = new DomainManager(10, matchingFunc, domainMatchingFunc);\n\n        // 1. Populate rmMap with a target domain that is NOT equal to the domain used in the second addLink call\n        manager.addLink(\"user1\", \"role1\", \"target_domain\");\n\n        // 2. Verify internal state via reflection to ensure \"target_domain\" RoleManager exists\n        Field rmMapField = DomainManager.class.getDeclaredField(\"rmMap\");\n        rmMapField.setAccessible(true);\n        Object rmMapObj = rmMapField.get(manager);\n        assertNotNull(\"rmMap should not be null\", rmMapObj);\n        assertTrue(\"rmMap should be a Map\", rmMapObj instanceof Map);\n        Map<?, ?> map = (Map<?, ?>) rmMapObj;\n        assertFalse(\"rmMap should contain target_domain\", map.isEmpty());\n\n        // 3. Add link to a different domain \"source_domain\".\n        // Because domainMatchingFunc returns true, the logic should propagate this link to \"target_domain\".\n        manager.addLink(\"user2\", \"role2\", \"source_domain\");\n\n        // 4. Verify propagation: \"target_domain\" should now have the link (\"user2\", \"role2\")\n        assertTrue(\"Link should be propagated to target_domain\",\n                   manager.hasLink(\"user2\", \"role2\", \"target_domain\"));\n\n        // Also verify it exists in the source\n        assertTrue(\"Link should exist in source_domain\",\n                   manager.hasLink(\"user2\", \"role2\", \"source_domain\"));\n    }\n\n    @Test\n    public void testAddLinkNoPropagationWhenFuncNull() {\n        // Ensure that when domainMatchingFunc is null, no extra iteration/propagation occurs\n        domainManager.addLink(\"alice\", \"admin\", \"domain1\");\n        domainManager.addLink(\"bob\", \"user\", \"domain2\");\n\n        // Verify links exist in their own domains\n        assertTrue(domainManager.hasLink(\"alice\", \"admin\", \"domain1\"));\n        assertTrue(domainManager.hasLink(\"bob\", \"user\", \"domain2\"));\n\n        // Verify they did NOT leak (since matchingFunc is null, propagation is skipped)\n        assertFalse(domainManager.hasLink(\"bob\", \"user\", \"domain1\"));\n        assertFalse(domainManager.hasLink(\"alice\", \"admin\", \"domain2\"));\n    }\n\n    @Test\n    public void testAddLinkDoesNotPropagateIfDomainDoesNotMatch() {\n        BiPredicate<String, String> domainMatchingFunc = (s1, s2) -> s1.equals(s2);\n        DomainManager manager = new DomainManager(10, null, domainMatchingFunc);\n\n        // Setup: Create RoleManager for domain1\n        manager.addLink(\"u1\", \"r1\", \"domain1\");\n\n        // Action: Add link to domain2.\n        // Since \"domain1\".equals(\"domain2\") is false, no propagation should happen to domain1.\n        manager.addLink(\"u2\", \"r2\", \"domain2\");\n\n        // Verification\n        assertTrue(manager.hasLink(\"u1\", \"r1\", \"domain1\"));\n        assertFalse(\"Link from domain2 should not propagate to domain1\",\n                    manager.hasLink(\"u2\", \"r2\", \"domain1\"));\n        assertTrue(manager.hasLink(\"u2\", \"r2\", \"domain2\"));\n    }\n}"

